{"implementation":"def solve(case):
    segments = case['segments']
    budget = case['budget']
    if not isinstance(segments, list) or len(segments) == 0:
        raise ValueError("segments must be a non-empty list")
    for s in segments:
        if not all(k in s for k in ('name','importance','minimum','capacity')):
            raise ValueError("segment missing required field")
    sum_min = sum(s['minimum'] for s in segments)
    sum_cap = sum(s['capacity'] for s in segments)
    if budget < sum_min or budget > sum_cap:
        raise ValueError("budget out of range")
    n = len(segments)
    allocations = [s['minimum'] for s in segments]
    remaining = budget - sum_min
    importances = [s['importance'] for s in segments]
    capacities = [s['capacity'] for s in segments]
    while remaining > 0:
        best_idx = -1
        best_score = -1.0
        for i in range(n):
            if allocations[i] < capacities[i]:
                score = importances[i] / (allocations[i] + 1)
                if score > best_score:
                    best_score = score
                    best_idx = i
        if best_idx == -1:
            raise ValueError("cannot allocate remaining budget")
        allocations[best_idx] += 1
        remaining -= 1
    total = budget
    by_name = {segments[i]['name']: allocations[i] for i in range(n)}
    return {"allocations": allocations, "by_name": by_name, "total": total}
"}
